package logfan

import (
	"context"
	"errors"
	"log/slog"
	"sync"
)

// Ring is an in-memory ring-buffer [slog.Handler] that keeps the most recent
// capacity records.
type Ring struct {
	mu         sync.RWMutex
	records    []slog.Record
	head       int
	count      int
	capacity   int
	preAttrs   []slog.Attr
	openGroups []string
}

// NewRing creates an in-memory ring-buffer slog handler keeping the most
// recent capacity records.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, errors.New("logfan: capacity must be positive")
	}
	return &Ring{
		records:  make([]slog.Record, capacity),
		capacity: capacity,
	}, nil
}

// Records returns the buffered records, oldest first. The returned slice is a
// deep copy — mutating it does not affect the ring.
func (r *Ring) Records() []slog.Record {
	r.mu.RLock()
	defer r.mu.RUnlock()

	n := r.count
	if n == 0 {
		return nil
	}

	out := make([]slog.Record, n)
	if n < r.capacity {
		for i := 0; i < n; i++ {
			out[i] = r.records[i].Clone()
		}
	} else {
		for i := 0; i < n; i++ {
			out[i] = r.records[(r.head+i)%r.capacity].Clone()
		}
	}
	return out
}

// Enabled implements slog.Handler. The ring accepts all levels.
func (r *Ring) Enabled(_ context.Context, _ slog.Level) bool {
	return true
}

// Handle implements slog.Handler.
func (r *Ring) Handle(_ context.Context, rec slog.Record) error {
	rec = rec.Clone()
	if len(r.preAttrs) > 0 {
		rec.AddAttrs(r.preAttrs...)
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	if r.count < r.capacity {
		r.records[(r.head+r.count)%r.capacity] = rec
		r.count++
	} else {
		r.records[r.head] = rec
		r.head = (r.head + 1) % r.capacity
	}
	return nil
}

// WithAttrs implements slog.Handler.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	h2 := &Ring{
		records:    make([]slog.Record, r.capacity),
		capacity:   r.capacity,
		preAttrs:   make([]slog.Attr, len(r.preAttrs), len(r.preAttrs)+len(attrs)),
		openGroups: append([]string{}, r.openGroups...),
	}
	copy(h2.preAttrs, r.preAttrs)
	h2.preAttrs = append(h2.preAttrs, prefixAttrs(r.openGroups, attrs)...)
	return h2
}

// WithGroup implements slog.Handler.
func (r *Ring) WithGroup(name string) slog.Handler {
	h2 := &Ring{
		records:    make([]slog.Record, r.capacity),
		capacity:   r.capacity,
		preAttrs:   append([]slog.Attr{}, r.preAttrs...),
		openGroups: append(append([]string{}, r.openGroups...), name),
	}
	return h2
}

// prefixAttrs wraps attrs in nested slog.Group calls according to the open
// group stack, innermost first.
func prefixAttrs(groups []string, attrs []slog.Attr) []slog.Attr {
	if len(groups) == 0 {
		return attrs
	}
	wrapped := attrs
	for i := len(groups) - 1; i >= 0; i-- {
		wrapped = []slog.Attr{slog.Group(groups[i], wrapped...)}
	}
	return wrapped
}

// multiHandler fans out every record to all its underlying handlers.
type multiHandler struct {
	handlers []slog.Handler
}

func (h *multiHandler) Enabled(ctx context.Context, level slog.Level) bool {
	for _, hh := range h.handlers {
		if hh.Enabled(ctx, level) {
			return true
		}
	}
	return false
}

func (h *multiHandler) Handle(ctx context.Context, rec slog.Record) error {
	for _, hh := range h.handlers {
		if !hh.Enabled(ctx, rec.Level) {
			continue
		}
		if err := hh.Handle(ctx, rec.Clone()); err != nil {
			return err
		}
	}
	return nil
}

func (h *multiHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	handlers := make([]slog.Handler, len(h.handlers))
	for i, hh := range h.handlers {
		handlers[i] = hh.WithAttrs(attrs)
	}
	return &multiHandler{handlers: handlers}
}

func (h *multiHandler) WithGroup(name string) slog.Handler {
	handlers := make([]slog.Handler, len(h.handlers))
	for i, hh := range h.handlers {
		handlers[i] = hh.WithGroup(name)
	}
	return &multiHandler{handlers: handlers}
}

// New builds a logger that delivers every record to ALL given handlers.
func New(handlers ...slog.Handler) (*slog.Logger, error) {
	if len(handlers) == 0 {
		return nil, errors.New("logfan: at least one handler required")
	}
	return slog.New(&multiHandler{handlers: handlers}), nil
}

package logfan

import (
	"context"
	"log/slog"
	"sync"
	"testing"
)

func TestNewRing_InvalidCapacity(t *testing.T) {
	_, err := NewRing(0)
	if err == nil {
		t.Error("expected error for capacity 0")
	}
	_, err = NewRing(-1)
	if err == nil {
		t.Error("expected error for capacity -1")
	}
}

func TestNewRing_Valid(t *testing.T) {
	r, err := NewRing(5)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if r == nil {
		t.Fatal("expected non-nil *Ring")
	}
}

func TestRing_Empty(t *testing.T) {
	r, _ := NewRing(3)
	recs := r.Records()
	if recs != nil {
		t.Errorf("expected nil, got %v", recs)
	}
}

func TestRing_OrderPreserved(t *testing.T) {
	r, _ := NewRing(5)
	h := slog.New(r)

	h.Info("one")
	h.Info("two")
	h.Info("three")

	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("expected 3 records, got %d", len(recs))
	}
	msgs := []string{"one", "two", "three"}
	for i, rec := range recs {
		if rec.Message != msgs[i] {
			t.Errorf("record %d: message=%q, want %q", i, rec.Message, msgs[i])
		}
	}
}

func TestRing_EvictsOldest(t *testing.T) {
	r, _ := NewRing(2)
	h := slog.New(r)

	h.Info("a")
	h.Info("b")
	h.Info("c")

	recs := r.Records()
	if len(recs) != 2 {
		t.Fatalf("expected 2 records, got %d", len(recs))
	}
	if recs[0].Message != "b" {
		t.Errorf("oldest: message=%q, want %q", recs[0].Message, "b")
	}
	if recs[1].Message != "c" {
		t.Errorf("newest: message=%q, want %q", recs[1].Message, "c")
	}
}

func TestRing_EvictAll(t *testing.T) {
	r, _ := NewRing(1)
	h := slog.New(r)

	h.Info("x")
	h.Info("y")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	if recs[0].Message != "y" {
		t.Errorf("message=%q, want %q", recs[0].Message, "y")
	}
}

func TestRing_RecordsAreCopies(t *testing.T) {
	r, _ := NewRing(5)
	h := slog.New(r)

	h.Info("original", "key", "value")

	recs := r.Records()
	recs[0].Message = "mutated"

	// Read again — ring must be unaffected
	recs2 := r.Records()
	if recs2[0].Message != "original" {
		t.Errorf("ring mutated: message=%q", recs2[0].Message)
	}
}

func TestRing_RecordsAreDeepCopied(t *testing.T) {
	r, _ := NewRing(5)
	h := slog.New(r)

	h.Info("test", "k", "v")

	recs := r.Records()
	recs[0].AddAttrs(slog.Int("extra", 99))

	recs2 := r.Records()
	var count int
	recs2[0].Attrs(func(a slog.Attr) bool {
		count++
		if a.Key == "extra" {
			t.Error("extra attr leaked into ring")
		}
		return true
	})
	// original attr "k" should still be there, "extra" should not
	if count != 1 {
		t.Logf("attributed count: %d", count)
	}
}

func TestRing_Concurrency(t *testing.T) {
	r, _ := NewRing(100)
	h := slog.New(r)

	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			h.Info("msg", "n", n)
		}(i)
	}
	wg.Wait()

	// Concurrent reads while writing
	var wg2 sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg2.Add(1)
		go func() {
			defer wg2.Done()
			h.Info("concurrent")
			_ = r.Records()
		}()
	}
	wg2.Wait()

	if len(r.Records()) == 0 {
		t.Error("expected records after concurrent access")
	}
}

func TestNew_NoHandlers(t *testing.T) {
	_, err := New()
	if err == nil {
		t.Error("expected error")
	}
}

func TestNew_SingleHandler(t *testing.T) {
	r, _ := NewRing(3)
	logger, err := New(r)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	logger.Info("hello")
	if len(r.Records()) != 1 {
		t.Error("expected 1 record")
	}
}

func TestNew_FanOut(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)

	logger, err := New(r1, r2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	logger.Info("hello")

	if len(r1.Records()) != 1 {
		t.Error("r1 should have 1 record")
	}
	if len(r2.Records()) != 1 {
		t.Error("r2 should have 1 record")
	}
}

func TestNew_FanOutMessages(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)

	logger, err := New(r1, r2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	logger.Info("a")
	logger.Warn("b")
	logger.Error("c")

	recs1 := r1.Records()
	recs2 := r2.Records()

	if len(recs1) != 3 || len(recs2) != 3 {
		t.Fatalf("expected 3 records each, got %d and %d", len(recs1), len(recs2))
	}
	for i := 0; i < 3; i++ {
		if recs1[i].Message != recs2[i].Message {
			t.Errorf("record %d mismatch: r1=%q r2=%q", i, recs1[i].Message, recs2[i].Message)
		}
	}
}

func TestRing_WithAttrs(t *testing.T) {
	r, _ := NewRing(5)
	h := r.WithAttrs([]slog.Attr{slog.String("env", "test")})

	slog.New(h).Info("msg")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "env" {
			found = true
			return false
		}
		return true
	})
	if !found {
		t.Error("attr env=test not found on record")
	}
}

func TestRing_WithGroup(t *testing.T) {
	r, _ := NewRing(5)
	h := r.WithGroup("request")
	h = h.WithAttrs([]slog.Attr{slog.String("id", "abc")})

	slog.New(h).Info("msg")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "request" && a.Value.Kind() == slog.KindGroup {
			for _, inner := range a.Value.Group() {
				if inner.Key == "id" && inner.Value.String() == "abc" {
					found = true
					return false
				}
			}
		}
		return true
	})
	if !found {
		t.Error("no request.id attr found on record")
	}
}

func TestMultiHandler_WithAttrsPropagates(t *testing.T) {
	r, _ := NewRing(5)
	mh := &multiHandler{handlers: []slog.Handler{r}}
	mh2 := mh.WithAttrs([]slog.Attr{slog.String("k", "v")})

	slog.New(mh2).Info("msg")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "k" {
			found = true
			return false
		}
		return true
	})
	if !found {
		t.Error("attr k=v not propagated via multiHandler.WithAttrs")
	}
}

func TestMultiHandler_WithGroupPropagates(t *testing.T) {
	r, _ := NewRing(5)
	mh := &multiHandler{handlers: []slog.Handler{r}}
	mh2 := mh.WithGroup("g").WithAttrs([]slog.Attr{slog.Int("n", 1)})

	slog.New(mh2).Info("msg")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "g" && a.Value.Kind() == slog.KindGroup {
			for _, inner := range a.Value.Group() {
				if inner.Key == "n" && inner.Value.Int64() == 1 {
					found = true
					return false
				}
			}
		}
		return true
	})
	if !found {
		t.Error("no g.n attr propagated via multiHandler.WithGroup")
	}
}

func TestRing_EnabledTrue(t *testing.T) {
	r, _ := NewRing(3)
	if !r.Enabled(context.Background(), slog.LevelDebug) {
		t.Error("expected Enabled=true for Debug")
	}
	if !r.Enabled(context.Background(), slog.LevelError) {
		t.Error("expected Enabled=true for Error")
	}
}

func TestMultiHandler_EnabledAny(t *testing.T) {
	r, _ := NewRing(3)
	mh := &multiHandler{handlers: []slog.Handler{r}}
	if !mh.Enabled(context.Background(), slog.LevelInfo) {
		t.Error("multiHandler.Enabled should return true when any handler is enabled")
	}
}

