func TestRing_Concurrency(t *testing.T) {
	r, _ := NewRing(100)
	h := slog.New(r)

	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			h.Info("msg", "n", n)
		}(i)
	}
	wg.Wait()

	// Concurrent reads while writing
	var wg2 sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg2.Add(1)
		go func() {
			defer wg2.Done()
			h.Info("concurrent")
			_ = r.Records()
		}()
	}
	wg2.Wait()

	if len(r.Records()) == 0 {
		t.Error("expected records after concurrent access")
