func TestMultiHandler_WithAttrsPropagates(t *testing.T) {
	r, _ := NewRing(5)
	mh := &multiHandler{handlers: []slog.Handler{r}}
	mh2 := mh.WithAttrs([]slog.Attr{slog.String("k", "v")})

	slog.New(mh2).Info("msg")

	inner := mh2.(*multiHandler).handlers[0].(*Ring)
	recs := inner.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "k" {
			found = true
			return false
		}
		return true
	})
	if !found {
		t.Error("attr k=v not propagated via multiHandler.WithAttrs")
	}
}
func TestMultiHandler_WithGroupPropagates(t *testing.T) {
	r, _ := NewRing(5)
	mh := &multiHandler{handlers: []slog.Handler{r}}
	mh2 := mh.WithGroup("g").WithAttrs([]slog.Attr{slog.Int("n", 1)})

	slog.New(mh2).Info("msg")

	inner := mh2.(*multiHandler).handlers[0].(*Ring)
	recs := inner.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}
	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "g" && a.Value.Kind() == slog.KindGroup {
			for _, inner := range a.Value.Group() {
				if inner.Key == "n" && inner.Value.Int64() == 1 {
					found = true
					return false
				}
			}
		}
		return true
	})
	if !found {
		t.Error("no g.n attr propagated via multiHandler.WithGroup")
	}
}

