func TestNew_FanOutWithAttrs(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)

	logger, err := New(r1, r2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	logger.With("k", "v").Info("msg")

	recs1 := r1.Records()
	recs2 := r2.Records()
	if len(recs1) != 1 || len(recs2) != 1 {
		t.Fatalf("expected 1 record each, got %d and %d", len(recs1), len(recs2))
	}

	for _, recs := range [][]slog.Record{recs1, recs2} {
		var found bool
		recs[0].Attrs(func(a slog.Attr) bool {
			if a.Key == "k" {
				found = true
				return false
			}
			return true
		})
		if !found {
			t.Error("attr k=v not propagated to both handlers via multi handler")
		}
	}
}

func TestNew_FanOutWithGroupAndAttrs(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)

	logger, err := New(r1, r2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	logger.WithGroup("g").With("n", 1).Info("msg")

	recs1 := r1.Records()
	recs2 := r2.Records()
	if len(recs1) != 1 || len(recs2) != 1 {
		t.Fatalf("expected 1 record each, got %d and %d", len(recs1), len(recs2))
	}

	for _, recs := range [][]slog.Record{recs1, recs2} {
		var found bool
		recs[0].Attrs(func(a slog.Attr) bool {
			if a.Key == "g" && a.Value.Kind() == slog.KindGroup {
				for _, inner := range a.Value.Group() {
					if inner.Key == "n" && inner.Value.Int64() == 1 {
						found = true
						return false
					}
				}
			}
			return true
		})
		if !found {
			t.Error("g.n attr not propagated to both handlers via multi handler")
		}
	}
}
	r, _ := NewRing(3)
	if !r.Enabled(context.Background(), slog.LevelDebug) {
		t.Error("expected Enabled=true for Debug")
	}
	if !r.Enabled(context.Background(), slog.LevelError) {
		t.Error("expected Enabled=true for Error")
	}
}

